mapper.select:
SELECT pc.id AS value, pc.name AS label FROM erp_stock st LEFT JOIN erp_product p ON p.id = st.product_id AND p.deleted = 0 INNER JOIN erp_product_category pc ON pc.id = p.category_id AND pc.deleted = b'0' LEFT JOIN erp_warehouse w ON w.id = st.warehouse_id AND w.deleted = 0 WHERE st.deleted = b'0' AND pc.status = 0
AND st.warehouse_id IN #{id}
AND st.warehouse_id = #{reqVO.warehouseId}
AND (pc.name LIKE CONCAT('%', #{reqVO.keyword}, '%') OR p.code LIKE CONCAT('%', #{reqVO.keyword}, '%') OR p.name LIKE CONCAT('%', #{reqVO.keyword}, '%'))
GROUP BY pc.id, pc.name ORDER BY MAX(pc.sort) ASC, pc.id DESC LIMIT 50

SELECT * FROM () page_rows
ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}

SELECT * FROM () page_rows
ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}

SELECT ${periodExpr} AS period,
       COALESCE(SUM(CASE WHEN IFNULL(sr.count, 0) > 0 THEN sr.count ELSE 0 END), 0) AS inCount,
       COALESCE(SUM(CASE WHEN IFNULL(sr.count, 0) > 0 THEN ABS(sr.total_price) ELSE 0 END), 0) AS inAmount,
       COALESCE(SUM(CASE WHEN IFNULL(sr.count, 0) < 0 THEN ABS(sr.count) ELSE 0 END), 0) AS outCount,
       COALESCE(SUM(CASE WHEN IFNULL(sr.count, 0) < 0 THEN ABS(sr.total_price) ELSE 0 END), 0) AS outAmount
FROM erp_stock_record sr
LEFT JOIN erp_stock st ON st.product_id = sr.product_id AND st.warehouse_id = sr.warehouse_id AND st.deleted = b'0'
LEFT JOIN erp_product p ON p.id = sr.product_id AND p.deleted = 0
LEFT JOIN erp_warehouse w ON w.id = sr.warehouse_id AND w.deleted = 0
WHERE sr.deleted = b'0'

    AND sr.warehouse_id IN #{id}

AND sr.warehouse_id = #{reqVO.warehouseId}
AND p.category_id = #{reqVO.categoryId}
AND sr.biz_date >= #{reqVO.startTime}
AND sr.biz_date <= #{reqVO.endTime}

    AND (p.code LIKE CONCAT('%', #{reqVO.keyword}, '%') OR p.name LIKE CONCAT('%', #{reqVO.keyword}, '%')
    OR w.name LIKE CONCAT('%', #{reqVO.keyword}, '%') OR sr.biz_no LIKE CONCAT('%', #{reqVO.keyword}, '%'))

GROUP BY ${periodExpr}
ORDER BY period ASC

SELECT * FROM () page_rows
ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}
